// Golden vectors for contracts/test/Golden.t.sol, produced by the TypeScript encoders the app uses (Grant.ts, Approval.ts,
// Invoice.ts). Regenerate from the repo root with `bun contracts/test/fixtures/golden.ts && bunx oxfmt -c oxfmt.config.ts
// contracts/test/fixtures/golden.json`, then commit golden.json.
// The approver key is forge's `makeAddrAndKey(APPROVER_LABEL)` (keccak256 of the label): a public test key, never a
// real one. Relative imports because the repo root has no viem; the chain package resolves its own dependencies.
import { writeFile } from 'node:fs/promises'
import { Effect } from 'effect'
import { makeApprover } from '../../../packages/chain/src/Approver.ts'
import { USDC } from '../../../packages/chain/src/Env.ts'
import { approvalArgs, policyTerms, singleExecution, transferCall } from '../../../packages/chain/src/Grant.ts'
import { approvalDigest, approvalNonce } from '../../../packages/protocol/src/Approval.ts'
import { ARC_CHAIN_ID, invoiceHash, jsonHash } from '../../../packages/protocol/src/Invoice.ts'
import { keccak256Utf8 } from '../../../packages/protocol/src/Keccak.ts'

const ENFORCER = '0x00000000000000000000000000000000000e4f01'
const APPROVER_LABEL = 'vitaquack.golden.approver'
const CAFE = '0x000000000000000000000000000000000000c0de'
const BAKERY = '0x000000000000000000000000000000000000b4ce'
const RESTRICTED = '0x0000000000000000000000000000000000000bad'
const PER_PAYMENT_CAP = 300_000n
const RESTRICTED_AMOUNT = 500_000n
const IN_POLICY_AMOUNT = 100_000n
const EXPIRY = 1_794_000_300

const approver = makeApprover(keccak256Utf8(APPROVER_LABEL))
const allowlist = [CAFE, BAKERY] as const

const restrictedInvoiceHash = invoiceHash({
  merchantId: 'duck-cafe',
  id: 'aaaqeayeaudaocajbifqydiob4',
  payTo: RESTRICTED,
  asset: USDC,
  amount: RESTRICTED_AMOUNT,
  expiresAt: EXPIRY,
  linesHash: jsonHash([{ name: 'Cigarettes', qty: 1, sku: 'cigarettes', unitAmount: RESTRICTED_AMOUNT.toString() }]),
  rulesHash: jsonHash(['restricted']),
})
const unsigned = {
  invoiceHash: restrictedInvoiceHash,
  payee: RESTRICTED,
  amount: RESTRICTED_AMOUNT.toString(),
  expiry: EXPIRY,
}
const approval = { ...unsigned, nonce: approvalNonce(ENFORCER, unsigned) }
const signed = await Effect.runPromise(approver.sign(ENFORCER, approval))

const golden = {
  note: 'Generated by contracts/test/fixtures/golden.ts from the app encoders; do not edit by hand.',
  chainId: ARC_CHAIN_ID,
  enforcer: ENFORCER,
  approverLabel: APPROVER_LABEL,
  approver: approver.address,
  policy: {
    perPaymentCap: PER_PAYMENT_CAP.toString(),
    allowlist,
    approver: approver.address,
  },
  policyTerms: policyTerms({ perPaymentCap: PER_PAYMENT_CAP, allowlist, approver: approver.address }),
  approval,
  approvalDigest: approvalDigest(ENFORCER, approval),
  signature: signed.signature,
  approvalArgs: approvalArgs(signed),
  approvedExecution: singleExecution(USDC, transferCall(RESTRICTED, RESTRICTED_AMOUNT)),
  inPolicyExecution: singleExecution(USDC, transferCall(CAFE, IN_POLICY_AMOUNT)),
}

await writeFile(new URL('golden.json', import.meta.url), `${JSON.stringify(golden, null, 2)}\n`)
